const crypto = require('crypto');

const headers = $json.headers || {};
const sigHeader = headers['x-threatfusion-signature-256'] || headers['X-ThreatFusion-Signature-256'];
const idemKey = headers['x-idempotency-key'] || headers['X-Idempotency-Key'];
const hmacSecret = $env.THREATFUSION_SOAR_HMAC_SECRET;

let verified = false;
let callbackSignature = '';
let callbackIdemKey = '';

if (sigHeader && idemKey && hmacSecret && typeof hmacSecret === 'string' && hmacSecret.length >= 16) {
  try {
    const body = $json.body || {};
    const sortKeys = (obj) => {
      if (obj === null || typeof obj !== 'object') return obj;
      if (Array.isArray(obj)) return obj.map(sortKeys);
      return Object.keys(obj).sort().reduce((acc, k) => {
        acc[k] = sortKeys(obj[k]);
        return acc;
      }, {});
    };
    const canonicalPayload = JSON.stringify(sortKeys(body));
    const hmac = crypto.createHmac('sha256', hmacSecret);
    hmac.update(canonicalPayload);
    const expectedSig = hmac.digest('hex');

    const sigBuf = Buffer.from(String(sigHeader), 'hex');
    const expBuf = Buffer.from(expectedSig, 'hex');
    const sigMatches = sigBuf.length === expBuf.length && crypto.timingSafeEqual(sigBuf, expBuf);

    const expectedIdemPrefix = `idem_${body.playbook_id}_`;
    const idemValid = Boolean(idemKey && String(idemKey).startsWith(expectedIdemPrefix) && String(idemKey).length > expectedIdemPrefix.length);

    let ledgerValid = false;
    try {
      const res = await fetch('http://threatfusion-callback:8443/api/v1/soar/verify-state', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-ThreatFusion-Signature-256': String(sigHeader),
          'X-Idempotency-Key': String(idemKey),
        },
        body: canonicalPayload,
      });
      if (res.ok) {
        const data = await res.json();
        ledgerValid = Boolean(data && data.state_verified === true);
      }
    } catch (e) {
      ledgerValid = false;
    }

    if (sigMatches && idemValid && ledgerValid) {
      verified = true;
      callbackIdemKey = `${idemKey}_cb`;
      const cbPayload = {
        candidate_id: body.candidate_id,
        execution_id: body.execution_id || 'exec_auto',
        misp_correlated: true,
        n8n_status: 'completed',
        playbook_id: body.playbook_id,
        thehive_case_created: true
      };
      const cbCanonical = JSON.stringify(sortKeys(cbPayload));
      const cbHmac = crypto.createHmac('sha256', hmacSecret);
      cbHmac.update(cbCanonical);
      callbackSignature = cbHmac.digest('hex');
    }
  } catch (err) {
    verified = false;
  }
}

return {
  ...$json,
  hmac_and_ledger_verified: verified,
  callback_signature: callbackSignature,
  callback_idempotency_key: callbackIdemKey,
};
